(()=>{const pet=document.querySelector('#nexzoCompanion');if(!pet)return;const stage=pet.querySelector('.pet-stage'),art=pet.querySelector('#activePetArt');pet.classList.add('nx-pet-popup');pet.hidden=true;const orb=document.createElement('button');orb.id='nexzoPetOrb';orb.className='nx-pet-orb';orb.type='button';orb.setAttribute('aria-label','Open Pet Zone');orb.innerHTML=`<img src="${art?.src||'assets/pets/nexy.webp'}" alt="NEXZO pet"><i></i>`;document.body.append(orb);const close=()=>{pet.hidden=true;orb.hidden=false;pet.setAttribute('aria-hidden','true')},open=()=>{pet.hidden=false;orb.hidden=true;pet.setAttribute('aria-hidden','false')};orb.onclick=()=>pet.hidden?open():close();document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.addEventListener('click',e=>{if(!pet.hidden&&!pet.contains(e.target)&&e.target!==orb)close()});pet.querySelector('#companionViewAll')?.addEventListener('click',open);pet.querySelector('#petCustomize')?.addEventListener('click',open);const particles=(symbols)=>{const r=art.getBoundingClientRect();symbols.forEach((s,i)=>{const p=document.createElement('span');p.className='nx-particle';p.textContent=s;p.style.left=`${r.left+r.width/2}px`;p.style.top=`${r.top+r.height/2}px`;p.style.setProperty('--dx',`${(i-2)*28}px`);document.body.append(p);setTimeout(()=>p.remove(),1100)})};document.querySelector('[data-pet-care="feed"]')?.addEventListener('click',()=>{particles(['❤️','💛','💜','❤️','💛']);art.classList.remove('nx-pet-wiggle');void art.offsetWidth;art.classList.add('nx-pet-wiggle');document.querySelector('#petMood')?.replaceChildren(document.createTextNode('Happy · Fed!'));window.NEXZOShell?.toast?.('Nexy is happy! 🍪','success')});document.querySelector('[data-pet-care="play"]')?.addEventListener('click',()=>{particles(['⭐','✨','💫','⭐','✨']);art.classList.remove('nx-pet-bounce');void art.offsetWidth;art.classList.add('nx-pet-bounce');document.querySelector('#petMood')?.replaceChildren(document.createTextNode('Energetic · Playing!'));window.NEXZOShell?.toast?.('Quick break! Nexy enjoyed it ⭐','success')});})();
